<?php
$facets=is_array($facets??null)?$facets:['colors'=>[],'sizes'=>[],'min_price'=>0,'max_price'=>0];
$categories=is_array($categories??null)?$categories:[];
$categoryChildren=[];$categoryById=[];foreach($categories as $categoryOption)$categoryById[(int)$categoryOption['id']]=$categoryOption;foreach($categories as $categoryOption){$id=(int)$categoryOption['id'];$parentId=(int)($categoryOption['parent_id']??0);if($parentId>0&&!isset($categoryById[$parentId]))$parentId=0;$categoryChildren[$parentId][]=$id;}
$orderedCategories=[];$seenCategories=[];$flattenCategories=function(int $parentId,int $depth=0)use(&$flattenCategories,&$orderedCategories,&$seenCategories,$categoryChildren,$categoryById):void{foreach($categoryChildren[$parentId]??[] as $id){if(isset($seenCategories[$id]))continue;$seenCategories[$id]=true;$option=$categoryById[$id];$option['_depth']=min(6,$depth);$orderedCategories[]=$option;$flattenCategories($id,$depth+1);}};$flattenCategories(0);foreach($categories as $categoryOption)if(!isset($seenCategories[(int)$categoryOption['id']])){$categoryOption['_depth']=0;$orderedCategories[]=$categoryOption;}$categories=$orderedCategories;
$selectedCategoryIds=array_map('intval',$filters['categories']??[]);$expandedCategoryIds=[];foreach($selectedCategoryIds as $selectedId){$cursor=$categoryById[$selectedId]??null;while($cursor&&isset($cursor['parent_id'])&&$cursor['parent_id']!==null){$parentId=(int)$cursor['parent_id'];$expandedCategoryIds[$parentId]=true;$cursor=$categoryById[$parentId]??null;}}
$renderCategoryTree=function(int $parentId,int $depth=0)use(&$renderCategoryTree,$categoryChildren,$categoryById,$selectedCategoryIds,$expandedCategoryIds,$view):void{foreach($categoryChildren[$parentId]??[] as $id){$item=$categoryById[$id]??null;if(!$item)continue;$children=$categoryChildren[$id]??[];$hasChildren=(bool)$children;$expanded=isset($expandedCategoryIds[$id]);$panelId='catalog-category-children-'.$id;?><div class="catalog-category-node" style="--category-depth:<?= min(6,$depth) ?>"><div class="catalog-category-row"><label class="catalog-filter-option"><input type="checkbox" name="category[]" value="<?= $id ?>" <?= in_array($id,$selectedCategoryIds,true)?'checked':'' ?>><span><?= $view->e($item['name']) ?></span></label><?php if($hasChildren): ?><button class="catalog-category-toggle<?= $expanded?' is-expanded':'' ?>" type="button" data-category-name="<?= $view->e($item['name']) ?>" aria-controls="<?= $panelId ?>" aria-expanded="<?= $expanded?'true':'false' ?>" aria-label="<?= $view->e(($expanded?'Скрий':'Покажи').' подкатегориите на '.$item['name']) ?>"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 7.5 5 5 5-5"/></svg></button><?php endif; ?></div><?php if($hasChildren): ?><div class="catalog-category-children<?= $expanded?' is-expanded':'' ?>" id="<?= $panelId ?>" <?= $expanded?'':'inert' ?>><div class="catalog-category-children-inner"><?php $renderCategoryTree($id,$depth+1); ?></div></div><?php endif; ?></div><?php }};
?>
<aside class="catalog-sidebar" id="catalog-filters" aria-label="Филтри на продуктите">
  <form method="get" class="catalog-filter-form" data-live-catalog-filters>
    <input type="hidden" name="columns" value="<?= (int)($filters['columns']??4) ?>">
    <div class="catalog-filter-section">
      <h3>Цена (€)</h3>
      <div class="catalog-price-fields"><label><span>От</span><input type="number" name="min_price" min="0" step="0.01" placeholder="<?= $view->e(number_format((float)($facets['min_price']??0),2,'.','')) ?>" value="<?= $view->e($filters['min_price']??'') ?>"></label><label><span>До</span><input type="number" name="max_price" min="0" step="0.01" placeholder="<?= $view->e(number_format((float)($facets['max_price']??0),2,'.','')) ?>" value="<?= $view->e($filters['max_price']??'') ?>"></label></div>
    </div>
    <?php if(!empty($facets['colors'])): ?><fieldset class="catalog-filter-section"><legend>Цвят</legend><div class="catalog-filter-options"><?php foreach($facets['colors'] as $color): ?><label class="catalog-filter-option"><input type="checkbox" name="color[]" value="<?= $view->e($color['label']) ?>" <?= in_array($color['label'],$filters['colors']??[],true)?'checked':'' ?>><span class="catalog-filter-swatch" style="--filter-color:<?= $view->e($color['hex']?:'#ead0d6') ?>"></span><span><?= $view->e($color['label']) ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
    <?php if(!empty($facets['sizes'])): ?><fieldset class="catalog-filter-section"><legend>Размер</legend><div class="catalog-filter-options catalog-filter-options-compact"><?php foreach($facets['sizes'] as $size): ?><label class="catalog-filter-option"><input type="checkbox" name="size[]" value="<?= $view->e($size) ?>" <?= in_array($size,$filters['sizes']??[],true)?'checked':'' ?>><span><?= $view->e($size) ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
    <fieldset class="catalog-filter-section"><legend>Категории</legend><div class="catalog-category-tree"><?php $renderCategoryTree(0); ?></div></fieldset>
    <div class="catalog-special-filters"><label class="catalog-filter-option"><input type="checkbox" name="in_stock" value="1" <?= !empty($filters['in_stock'])?'checked':'' ?>><span>Само налични</span></label><label class="catalog-filter-option"><input type="checkbox" name="on_sale" value="1" <?= !empty($filters['on_sale'])?'checked':'' ?>><span>Само промоции</span></label></div>
    <div class="catalog-filter-section"><label class="catalog-sort-label" for="catalog-sort">Подреди</label><select id="catalog-sort" name="sort"><option value="latest" <?= ($filters['sort']??'latest')==='latest'?'selected':'' ?>>Най-нови</option><option value="price_asc" <?= ($filters['sort']??'')==='price_asc'?'selected':'' ?>>Цена: ниска към висока</option><option value="price_desc" <?= ($filters['sort']??'')==='price_desc'?'selected':'' ?>>Цена: висока към ниска</option><option value="name" <?= ($filters['sort']??'')==='name'?'selected':'' ?>>Име</option></select></div>
    <a class="catalog-clear-link" href="<?= isset($category)?'/category/'.$view->e($category['slug']):'/products' ?>">Изчисти филтрите</a>
  </form>
</aside>
<style>
.catalog-layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:20px;align-items:start}.catalog-layout.filters-collapsed{grid-template-columns:minmax(0,1fr)}.catalog-results{min-width:0}.catalog-sidebar{position:sticky;top:18px;background:transparent;border:0;border-radius:0;padding:0}.catalog-sidebar.is-collapsed{display:none}.catalog-filter-section{display:grid;gap:8px;margin:0 0 14px;padding:0 0 13px;border:0;border-bottom:1px solid var(--line)}.catalog-filter-section h3,.catalog-filter-section legend{margin:0 0 10px;padding:0;font-size:1.08rem;font-weight:400}.catalog-price-fields{display:grid;grid-template-columns:1fr 1fr;gap:8px}.catalog-price-fields label{display:grid;gap:5px;color:var(--muted);font-size:.88rem}.catalog-price-fields input,.catalog-filter-section select{width:100%;min-width:0;padding:10px 11px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink)}.catalog-filter-options{display:grid;gap:8px}.catalog-filter-options-compact{grid-template-columns:repeat(3,minmax(0,1fr))}.catalog-filter-option{display:flex;align-items:center;gap:9px;min-width:0;color:#544a49;font-size:.96rem;cursor:pointer}.catalog-filter-option input{width:17px;height:17px;flex:none;accent-color:var(--accent)}.catalog-filter-swatch{width:19px;height:19px;flex:none;border:1px solid #d5c8c8;border-radius:50%;background:var(--filter-color)}.catalog-category-tree{display:grid;gap:5px}.catalog-category-node{min-width:0}.catalog-category-row{display:flex;align-items:center;justify-content:space-between;gap:5px}.catalog-category-row>.catalog-filter-option{flex:1;min-width:0}.catalog-category-toggle{display:grid;width:32px;height:32px;flex:none;place-items:center;padding:0;border:1px solid transparent;border-radius:8px;background:transparent;color:#756b66;cursor:pointer;transition:background .18s,color .18s}.catalog-category-toggle:hover{background:#fff1f4;color:var(--accent-dark)}.catalog-category-toggle svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;transition:transform .24s ease}.catalog-category-toggle.is-expanded svg{transform:rotate(180deg)}.catalog-category-children{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .28s ease,opacity .22s ease}.catalog-category-children.is-expanded{grid-template-rows:1fr;opacity:1}.catalog-category-children-inner{min-height:0;overflow:hidden}.catalog-category-children-inner>.catalog-category-node{margin-left:17px;padding-left:10px;border-left:1px solid #f0dce1}.catalog-special-filters{display:grid;gap:10px;margin:0 0 18px}.catalog-sort-label{display:grid;gap:8px;color:var(--muted);font-size:.9rem}.catalog-clear-link{display:block;margin-top:13px;text-align:center;color:var(--muted);font-size:.92rem}
@media(max-width:760px){.catalog-layout,.catalog-layout.filters-collapsed{grid-template-columns:1fr;gap:12px}.catalog-sidebar{position:static;max-height:none}}
</style>
<script>
(()=>{if(window.__giftchetaLiveCatalogFilters)return;window.__giftchetaLiveCatalogFilters=true;let controller=null,timer=null;const find=selector=>document.querySelector(selector);async function load(url,{push=true}={}){clearTimeout(timer);const results=find('.catalog-results');if(!results)return;controller?.abort();controller=new AbortController();const activeController=controller;results.classList.add('is-loading');results.setAttribute('aria-busy','true');try{const response=await fetch(url,{signal:controller.signal,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});if(!response.ok)throw new Error('Catalog request failed');const html=await response.text(),doc=new DOMParser().parseFromString(html,'text/html'),nextResults=doc.querySelector('.catalog-results');if(!nextResults)throw new Error('Catalog results missing');results.querySelectorAll('style').forEach(style=>document.head.append(style.cloneNode(true)));nextResults.querySelectorAll('style,script').forEach(asset=>asset.remove());results.replaceWith(nextResults);if(push)history.pushState({},'',url);window.dispatchEvent(new CustomEvent('giftcheta:catalog-updated'));}catch(error){if(error.name!=='AbortError')window.location.assign(url)}finally{if(controller===activeController){const current=find('.catalog-results');current?.classList.remove('is-loading');current?.removeAttribute('aria-busy')}}}function formUrl(form){const url=new URL(form.action||location.href,location.origin);url.search=new URLSearchParams(new FormData(form)).toString();url.searchParams.delete('page');return url.pathname+url.search}document.addEventListener('click',event=>{const categoryToggle=event.target.closest('.catalog-category-toggle');if(categoryToggle){const panel=document.getElementById(categoryToggle.getAttribute('aria-controls'));if(!panel)return;const expanded=categoryToggle.getAttribute('aria-expanded')==='true';categoryToggle.setAttribute('aria-expanded',String(!expanded));categoryToggle.classList.toggle('is-expanded',!expanded);categoryToggle.setAttribute('aria-label',(expanded?'Покажи':'Скрий')+' подкатегориите на '+categoryToggle.dataset.categoryName);if(expanded){panel.classList.remove('is-expanded');window.setTimeout(()=>{if(categoryToggle.getAttribute('aria-expanded')==='false')panel.setAttribute('inert','')},300)}else{panel.removeAttribute('inert');panel.classList.add('is-expanded')}return}const toggle=event.target.closest('[data-catalog-filter-toggle]');if(toggle){const sidebar=find('#catalog-filters'),layout=sidebar?.closest('.catalog-layout');if(!sidebar||!layout)return;const collapsed=sidebar.classList.toggle('is-collapsed');layout.classList.toggle('filters-collapsed',collapsed);toggle.setAttribute('aria-controls','catalog-filters');toggle.setAttribute('aria-expanded',String(!collapsed));return}const link=event.target.closest('.catalog-results .pagination a');if(link&&link.origin===location.origin){event.preventDefault();load(link.pathname+link.search)}});document.addEventListener('submit',event=>{const form=event.target.closest('[data-live-catalog-filters]');if(!form)return;event.preventDefault();load(formUrl(form))});document.addEventListener('change',event=>{const form=event.target.closest('[data-live-catalog-filters]');if(!form)return;if(event.target.matches('input[type=checkbox], select'))load(formUrl(form))});document.addEventListener('input',event=>{if(!event.target.matches('[data-live-catalog-filters] input[type=number]'))return;clearTimeout(timer);timer=setTimeout(()=>load(formUrl(event.target.form)),450)});window.addEventListener('popstate',()=>load(location.pathname+location.search,{push:false}));})();
</script>
